body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
}

header {
    width: 100%;
    padding: 2rem 0;
    text-align: center;
    border-bottom: 1px solid var(--border-color);
    margin-bottom: 2rem;
}

h1 {
    margin: 0;
    font-size: 1.5rem;
    font-weight: 500;
}

main {
    width: 100%;
    max-width: 800px;
    padding: 0 1rem;
}

.image-preview-card {
    background-color: var(--card-bg);
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--border-color);
}

.image-container img {
    width: 100%;
    height: auto;
    display: block;
}

.actions {
    padding: 1.5rem;
    display: flex;
    justify-content: center;
}

.btn {
    padding: 0.75rem 1.5rem;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
    border: none;
}

.btn:active {
    transform: scale(0.98);
}

.btn:focus-visible {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

.btn-danger {
    background-color: var(--danger-color);
    color: #000;
}

.btn-danger:hover {
    background-color: var(--danger-hover);
    color: #fff;
}

.btn-secondary {
    background-color: var(--surface-color);
    color: var(--text-color);
}

.btn-secondary:hover {
    background-color: #3d3d3d;
}

/* Dialog Styling */
dialog {
    background-color: var(--card-bg);
    color: var(--text-color);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 0;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.8);
}

dialog::backdrop {
    background-color: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(4px);
}

.dialog-content {
    padding: 2rem;
}

dialog h2 {
    margin-top: 0;
    margin-bottom: 1rem;
    font-size: 1.25rem;
}

dialog p {
    color: var(--text-muted);
    line-height: 1.5;
    margin-bottom: 2rem;
}

.dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

/* Scroll lock when dialog is open */
body:has(dialog[open]) {
    overflow: hidden;
}
