document.addEventListener('DOMContentLoaded', () => {
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.querySelector('.trigger');
    const cancelBtn = document.getElementById('cancel-btn');
    const confirmBtn = document.getElementById('confirm-delete-btn');

    if (!dialog || !trigger || !cancelBtn || !confirmBtn) return;

    // Open dialog
    trigger.addEventListener('click', () => {
        dialog.showModal();
    });

    // Close dialog on cancel
    cancelBtn.addEventListener('click', () => {
        dialog.close();
    });

    // Handle delete confirmation
    confirmBtn.addEventListener('click', () => {
        console.log('Image deleted');
        // In a real app, you'd perform the deletion here.
        // For this demo, we'll just close the dialog and maybe hide the card.
        dialog.close();

        const card = document.querySelector('.image-preview-card');
        if (card) {
            card.style.opacity = '0.5';
            card.style.pointerEvents = 'none';
            trigger.disabled = true;
            trigger.textContent = 'Deleted';
        }
    });

    // Close on backdrop click (optional but common UX)
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );
        if (!isInDialog) {
            dialog.close();
        }
    });
});

